package cli

import (
	"fmt"
	"strconv"
	"strings"
)

// FindStanza locates a named stanza in content.
// Returns version, body, found. If not found, version=-1, body="", found=false.
func FindStanza(content, name string) (version int, body string, found bool) {
	beginPrefix := "# BEGIN " + name + " (v"
	endLine := "# END " + name

	lines := strings.Split(content, "\n")
	inStanza := false
	stanzaVersion := -1
	var bodyLines []string

	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if !inStanza {
			if strings.HasPrefix(trimmed, beginPrefix) && strings.HasSuffix(trimmed, ")") {
				// Extract version number
				vStr := trimmed[len(beginPrefix) : len(trimmed)-1]
				v, err := strconv.Atoi(vStr)
				if err != nil {
					continue
				}
				inStanza = true
				stanzaVersion = v
				bodyLines = nil
				continue
			}
		} else {
			if trimmed == endLine {
				return stanzaVersion, strings.Join(bodyLines, "\n"), true
			}
			bodyLines = append(bodyLines, line)
		}
	}

	return -1, "", false
}

// UpsertStanza inserts or replaces a named stanza. Returns new file content.
func UpsertStanza(content string, name string, version int, body string) string {
	beginPrefix := "# BEGIN " + name + " (v"
	endLine := "# END " + name
	beginLine := fmt.Sprintf("# BEGIN %s (v%d)", name, version)

	stanzaBlock := beginLine + "\n" + body + "\n" + endLine

	lines := strings.Split(content, "\n")
	var result []string
	inStanza := false
	replaced := false

	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if !inStanza {
			if strings.HasPrefix(trimmed, beginPrefix) && strings.HasSuffix(trimmed, ")") {
				// Validate it has a version number
				vStr := trimmed[len(beginPrefix) : len(trimmed)-1]
				if _, err := strconv.Atoi(vStr); err != nil {
					result = append(result, line)
					continue
				}
				inStanza = true
				// Add the replacement stanza
				result = append(result, stanzaBlock)
				replaced = true
				continue
			}
			result = append(result, line)
		} else {
			if trimmed == endLine {
				inStanza = false
			}
			// Skip old stanza lines (already replaced)
		}
	}

	if !replaced {
		// Append to end, ensuring a blank line separator
		trimmedContent := strings.TrimRight(content, "\n")
		if trimmedContent == "" {
			return stanzaBlock + "\n"
		}
		return trimmedContent + "\n\n" + stanzaBlock + "\n"
	}

	return strings.Join(result, "\n")
}

// RemoveStanza removes a named stanza. Returns content unchanged if not found.
func RemoveStanza(content, name string) string {
	beginPrefix := "# BEGIN " + name + " (v"
	endLine := "# END " + name

	lines := strings.Split(content, "\n")
	var result []string
	inStanza := false
	found := false
	// Track index where stanza starts to remove preceding blank line
	stanzaStartIdx := -1

	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if !inStanza {
			if strings.HasPrefix(trimmed, beginPrefix) && strings.HasSuffix(trimmed, ")") {
				// Validate it has a version number
				vStr := trimmed[len(beginPrefix) : len(trimmed)-1]
				if _, err := strconv.Atoi(vStr); err != nil {
					result = append(result, line)
					continue
				}
				inStanza = true
				found = true
				stanzaStartIdx = len(result)
				continue
			}
			result = append(result, line)
		} else {
			if trimmed == endLine {
				inStanza = false
				// Remove trailing blank line after stanza if present
				// (will be handled below)
				continue
			}
			// Skip stanza body lines
		}
	}

	if !found {
		return content
	}

	// Remove blank line before the stanza if it exists
	if stanzaStartIdx > 0 && strings.TrimSpace(result[stanzaStartIdx-1]) == "" {
		result = append(result[:stanzaStartIdx-1], result[stanzaStartIdx:]...)
	}

	// Clean up trailing empty lines — keep at most one trailing newline
	output := strings.Join(result, "\n")
	output = strings.TrimRight(output, "\n")
	if output != "" {
		output += "\n"
	}

	return output
}

package cli

import (
	"testing"
)

func TestFindStanza_Present(t *testing.T) {
	content := `# some config
export FOO=bar

# BEGIN my-tool (v2)
source <(my-tool completion bash)
# END my-tool

export BAZ=qux
`
	version, body, found := FindStanza(content, "my-tool")
	if !found {
		t.Fatal("expected stanza to be found")
	}
	if version != 2 {
		t.Errorf("version = %d, want 2", version)
	}
	if body != "source <(my-tool completion bash)" {
		t.Errorf("body = %q, want %q", body, "source <(my-tool completion bash)")
	}
}

func TestFindStanza_Absent(t *testing.T) {
	content := `export FOO=bar
`
	version, body, found := FindStanza(content, "my-tool")
	if found {
		t.Fatal("expected stanza to not be found")
	}
	if version != -1 {
		t.Errorf("version = %d, want -1", version)
	}
	if body != "" {
		t.Errorf("body = %q, want empty", body)
	}
}

func TestFindStanza_DifferentName(t *testing.T) {
	content := `# BEGIN other-tool (v1)
something
# END other-tool
`
	_, _, found := FindStanza(content, "my-tool")
	if found {
		t.Fatal("should not find stanza with different name")
	}
}

func TestFindStanza_MultilineBody(t *testing.T) {
	content := `# BEGIN my-tool (v1)
line1
line2
line3
# END my-tool
`
	version, body, found := FindStanza(content, "my-tool")
	if !found {
		t.Fatal("expected stanza to be found")
	}
	if version != 1 {
		t.Errorf("version = %d, want 1", version)
	}
	if body != "line1\nline2\nline3" {
		t.Errorf("body = %q, want %q", body, "line1\nline2\nline3")
	}
}

func TestUpsertStanza_EmptyContent(t *testing.T) {
	result := UpsertStanza("", "my-tool", 1, "source <(my-tool completion bash)")
	want := "# BEGIN my-tool (v1)\nsource <(my-tool completion bash)\n# END my-tool\n"
	if result != want {
		t.Errorf("result = %q, want %q", result, want)
	}
}

func TestUpsertStanza_AppendToExistingContent(t *testing.T) {
	content := "export FOO=bar\n"
	result := UpsertStanza(content, "my-tool", 1, "source <(my-tool completion bash)")
	want := "export FOO=bar\n\n# BEGIN my-tool (v1)\nsource <(my-tool completion bash)\n# END my-tool\n"
	if result != want {
		t.Errorf("result = %q, want %q", result, want)
	}
}

func TestUpsertStanza_ReplaceExisting(t *testing.T) {
	content := `export FOO=bar

# BEGIN my-tool (v1)
old-command
# END my-tool

export BAZ=qux
`
	result := UpsertStanza(content, "my-tool", 2, "new-command")
	want := `export FOO=bar

# BEGIN my-tool (v2)
new-command
# END my-tool

export BAZ=qux
`
	if result != want {
		t.Errorf("result = %q, want %q", result, want)
	}
}

func TestUpsertStanza_PreservesSurroundingContent(t *testing.T) {
	content := `# header
export A=1

# BEGIN my-tool (v1)
old-line
# END my-tool

# footer
export B=2
`
	result := UpsertStanza(content, "my-tool", 2, "new-line")

	// Check surrounding content is preserved
	if !containsLine(result, "# header") {
		t.Error("header should be preserved")
	}
	if !containsLine(result, "export A=1") {
		t.Error("content before stanza should be preserved")
	}
	if !containsLine(result, "# footer") {
		t.Error("footer should be preserved")
	}
	if !containsLine(result, "export B=2") {
		t.Error("content after stanza should be preserved")
	}
}

func TestUpsertStanza_NoTrailingNewline(t *testing.T) {
	content := "export FOO=bar"
	result := UpsertStanza(content, "my-tool", 1, "cmd")
	want := "export FOO=bar\n\n# BEGIN my-tool (v1)\ncmd\n# END my-tool\n"
	if result != want {
		t.Errorf("result = %q, want %q", result, want)
	}
}

func TestUpsertStanza_MultipleStanzas(t *testing.T) {
	content := `# BEGIN tool-a (v1)
cmd-a
# END tool-a
`
	result := UpsertStanza(content, "tool-b", 1, "cmd-b")
	// tool-a should remain, tool-b appended
	_, _, foundA := FindStanza(result, "tool-a")
	if !foundA {
		t.Error("tool-a stanza should still exist")
	}
	_, _, foundB := FindStanza(result, "tool-b")
	if !foundB {
		t.Error("tool-b stanza should be appended")
	}
}

func TestRemoveStanza_Present(t *testing.T) {
	content := `export FOO=bar

# BEGIN my-tool (v1)
source <(my-tool completion bash)
# END my-tool

export BAZ=qux
`
	result := RemoveStanza(content, "my-tool")
	if containsLine(result, "# BEGIN my-tool") {
		t.Error("stanza BEGIN marker should be removed")
	}
	if containsLine(result, "# END my-tool") {
		t.Error("stanza END marker should be removed")
	}
	if containsLine(result, "my-tool completion") {
		t.Error("stanza body should be removed")
	}
	if !containsLine(result, "export FOO=bar") {
		t.Error("content before stanza should be preserved")
	}
	if !containsLine(result, "export BAZ=qux") {
		t.Error("content after stanza should be preserved")
	}
}

func TestRemoveStanza_Absent(t *testing.T) {
	content := "export FOO=bar\n"
	result := RemoveStanza(content, "my-tool")
	if result != content {
		t.Errorf("content should be unchanged, got %q", result)
	}
}

func TestRemoveStanza_AtBeginning(t *testing.T) {
	content := `# BEGIN my-tool (v1)
cmd
# END my-tool

export FOO=bar
`
	result := RemoveStanza(content, "my-tool")
	if containsLine(result, "# BEGIN my-tool") {
		t.Error("stanza should be removed")
	}
	if !containsLine(result, "export FOO=bar") {
		t.Error("remaining content should be preserved")
	}
}

func TestRemoveStanza_AtEnd(t *testing.T) {
	content := `export FOO=bar

# BEGIN my-tool (v1)
cmd
# END my-tool
`
	result := RemoveStanza(content, "my-tool")
	if containsLine(result, "# BEGIN my-tool") {
		t.Error("stanza should be removed")
	}
	if !containsLine(result, "export FOO=bar") {
		t.Error("remaining content should be preserved")
	}
}

func TestRemoveStanza_OnlyStanza(t *testing.T) {
	content := `# BEGIN my-tool (v1)
cmd
# END my-tool
`
	result := RemoveStanza(content, "my-tool")
	// Should result in empty or whitespace-only content
	if containsLine(result, "# BEGIN my-tool") {
		t.Error("stanza should be removed")
	}
}

func TestRemoveStanza_PreservesOtherStanzas(t *testing.T) {
	content := `# BEGIN tool-a (v1)
cmd-a
# END tool-a

# BEGIN tool-b (v1)
cmd-b
# END tool-b
`
	result := RemoveStanza(content, "tool-a")
	_, _, foundA := FindStanza(result, "tool-a")
	if foundA {
		t.Error("tool-a should be removed")
	}
	_, _, foundB := FindStanza(result, "tool-b")
	if !foundB {
		t.Error("tool-b should be preserved")
	}
}

func containsLine(content, line string) bool {
	for _, l := range splitLines(content) {
		if l == line {
			return true
		}
	}
	return false
}

func splitLines(s string) []string {
	lines := make([]string, 0)
	for _, line := range split(s, "\n") {
		lines = append(lines, line)
	}
	return lines
}

func split(s, sep string) []string {
	if s == "" {
		return nil
	}
	result := make([]string, 0)
	for {
		idx := indexOf(s, sep)
		if idx < 0 {
			result = append(result, s)
			break
		}
		result = append(result, s[:idx])
		s = s[idx+len(sep):]
	}
	return result
}

func indexOf(s, sub string) int {
	for i := range len(s) - len(sub) + 1 {
		if s[i:i+len(sub)] == sub {
			return i
		}
	}
	return -1
}

